import React from 'react';

function About() {
  return (
    <section id="about" className="py-20 bg-gray-800 text-white">
      <div className="container mx-auto px-4">
        <h2 className="text-4xl font-bold text-center mb-12 text-blue-400">About Me</h2>
        <div className="max-w-3xl mx-auto text-lg leading-relaxed">
          <p className="mb-6">
            Hello! I'm Manoj Kumar R, a passionate and dedicated Frontend and UI Developer with a keen eye for detail and a love for creating intuitive, engaging, and visually stunning web experiences. My journey in web development began with a fascination for how design translates into interactive digital products, and it has since evolved into a commitment to crafting high-quality, user-centric interfaces.
          </p>
          <p className="mb-6">
            I specialize in building responsive and performant web applications using modern JavaScript frameworks and libraries. My expertise lies in transforming complex design concepts into clean, efficient, and maintainable code, ensuring a seamless user experience across all devices.
          </p>
          <p>
            I am constantly exploring new technologies and best practices to stay at the forefront of frontend development. I thrive in collaborative environments where I can contribute to innovative solutions and continuously learn from my peers. Let's build something amazing together!
          </p>
        </div>
      </div>
    </section>
  );
}

export default About;
